# এসএসসি সাধারণ গণিত অধ্যায় ৪ (সূচক ও লগারিদম) ও ৫ (এক চলকবিশিষ্ট সমীকরণ): প্রতি অনুশীলনী ৩০টি
from sqlib import *
import sympy as sp, math
x,n,a=sp.symbols('x n a',real=True)
S=lambda e:sp.simplify(e)
def sol(eq,var=x): return sorted(sp.solve(eq,var),key=lambda v:float(v))
L2,L3,L7=0.3010,0.4771,0.8451
ap=lambda u,v:abs(u-v)<6e-4
# ---- 4.1 ----
assert S((2**(n+4)-4*2**n)/(2*2**(n+3)))==sp.Rational(3,4) and S((3**(n+2)-3**n)/(3**(n+1)+3**n))==2
assert sol(2**(x+1)-32)==[4] and sol(3**(2*x-1)-27)==[2] and sol(4**x-8)==[sp.Rational(3,2)] and sol(9**x-3**(x+2))==[2]
assert sol(2**x+2**(x+1)-48)==[4] and sol(5**(x+1)+5**x-750)==[3]
assert sp.Integer(27)**sp.Rational(2,3)*sp.Integer(16)**sp.Rational(-3,4)==sp.Rational(9,8) and sp.Integer(64)**sp.Rational(-2,3)/sp.Rational(1,8)**sp.Rational(1,3)==sp.Rational(1,8)
assert sp.simplify((sp.sqrt(a)*a**sp.Rational(1,3))**6-a**5)==0
assert sol(2**(2*x)-5*2**x+4)==[0,2] and sol(3**(2*x)-10*3**x+9)==[0,2] and sol(4**(x+1)-2**(3*x-1))==[3]
assert S(2**n*6**(n+1)/(3**n*4**(n+1)))==sp.Rational(3,2) and S((5**(n+3)-6*5**(n+1))/(9*5**n-4*5**n))==19
assert sp.simplify(sp.sqrt(2*sp.sqrt(2*sp.sqrt(2)))-2**sp.Rational(7,8))==0
xx=2**sp.Rational(1,3)+2**sp.Rational(-1,3); assert sp.simplify(sp.expand(2*xx**3-6*xx))==5
assert 3**2-2==7 and (4,2)==(2*2,2) and sol((sp.Rational(1,2))**(x-1)-16)==[-3]
assert sp.Rational(8,1000)**sp.Rational(-2,3)==25 and sp.Rational(8*9,4*27)==sp.Rational(2,3) and sol(2**(x+3)+2**(x+1)-320)==[5] and sp.Integer(81)**sp.Rational(3,4)==27
